/// Decode a client packet payload by wire index (same dispatch as the enum).
pub fn decode_client_packet(
    index: i16,
    payload: &[u8],
) -> Result<ClientPacket, crate::ProtocolError> {
    ClientPacket::decode(index, payload)
}

